content.css:
@font-face {
  font-family: 'Plus Jakarta Sans';
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2-variations');
}
.visual-root {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  gap: 16px;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden auto;
  background: transparent;
  font-weight: 400;
  font-variation-settings: "wght" 400;
  --ds-color-ink: #131B33;
  --ds-color-ink-soft: #4C5378;
  --ds-color-surface: #FFFFFF;
  --ds-color-line: #DDE2F0;
  --ds-color-amber: #B9700A;
  --ds-color-blue: #0A4EE4;
  --ds-shadow-card: 0 1px 2px rgba(19, 27, 51, 0.04), 0 8px 24px -12px rgba(19, 27, 51, 0.18);
}
.kpi-card {
  flex: 1 1 140px;
  min-width: 140px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  box-sizing: border-box;
  padding: 20px 24px;
  border-radius: 18px;
  border: 1px solid var(--ds-color-line);
  background: var(--ds-color-surface);
  box-shadow: var(--ds-shadow-card);
}
.kpi-card-label {
  font-size: 0.72rem;
  line-height: 1.4;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ds-color-ink-soft);
  font-weight: 700;
  font-variation-settings: "wght" 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-card-value {
  font-size: 2.1rem;
  line-height: 1;
  color: var(--ds-color-ink);
  font-weight: 800;
  font-variation-settings: "wght" 800;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-card--atencao .kpi-card-value {
  color: var(--ds-color-amber);
}
.kpi-card--destaque {
  background: var(--ds-color-blue);
  border-color: var(--ds-color-blue);
}
.kpi-card--destaque .kpi-card-label {
  color: rgba(255, 255, 255, 0.82);
}
.kpi-card--destaque .kpi-card-value {
  color: #fff;
}
.empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: var(--ds-color-ink-soft);
  font-size: 0.9rem;
  text-align: center;
  padding: 16px;
  box-sizing: border-box;
}
